UPDATE ESS_LEAVE_APPLY_TB
   SET SEND_EMAIL_FLAG = 1
     WHERE APPLY_NO = #{applyNo, jdbcType=VARCHAR}

        UPDATE ESS_LEAVE_APPLY_TB
			   SET ATTENDACE_FLAG = 1
             WHERE APPLY_NO = #{APPLY_NO, jdbcType=VARCHAR}

UPDATE SY_AFFIRM_EMAIL A
   SET A.SEND_FLAG = #{SEND_FINISH_FLAG, jdbcType=NUMERIC}
 WHERE A.SEQ = #{SEQ, jdbcType=NUMERIC}

